const r = await tools.mcp__codex_apps__github_search_prs({
  repository_full_name: "entireio/entire-graph",
  query: "Aikido in:title",
  state: "open",
  sort: "updated",
  order: "desc",
  topn: 50
});
for (const c of (r.content || [])) {
  if (c.type === "text") text(c.text);
  else if (c.type === "resource") text(c.resource?.text || "");
}

const r = await tools.mcp__codex_apps__github_search_prs({
  repository_full_name: "entireio/entire-graph",
  query: "Aikido in:title",
  state: "open",
  sort: "updated",
  order: "desc",
  topn: 50
});
text(JSON.stringify(r));

const r = await tools.exec_command({
  cmd: "cat .entire/graph-agent.md",
  workdir: "/Users/thomi/Projects/entire-graph",
  yield_time_ms: 10000,
  max_output_tokens: 20000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "pwd && git status --short --branch && ls -la .entire",
  workdir: "/Users/thomi/Projects/entire-graph",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

const prs = [88, 89, 90];
const bundles = await Promise.all(prs.map(async pr => {
  const [info, files, patch, comments, reviews] = await Promise.all([
    tools.mcp__codex_apps__github_get_pr_info({repository_full_name:"entireio/entire-graph", pr_number:pr}),
    tools.mcp__codex_apps__github_list_pr_changed_filenames({repo_full_name:"entireio/entire-graph", pr_number:pr}),
    tools.mcp__codex_apps__github_fetch_pr_patch({repo_full_name:"entireio/entire-graph", pr_number:pr}),
    tools.mcp__codex_apps__github_fetch_pr_comments({repo_full_name:"entireio/entire-graph", pr_number:pr}),
    tools.mcp__codex_apps__github_list_pull_request_reviews({repo_full_name:"entireio/entire-graph", pr_number:pr})
  ]);
  return {pr, info, files, patch, comments, reviews};
}));
store("aikido_pr_bundles", bundles);
for (const b of bundles) {
  text(`PR #${b.pr}\nINFO ${JSON.stringify(b.info.structuredContent)}\nFILES ${JSON.stringify(b.files.structuredContent)}\nCOMMENTS ${JSON.stringify(b.comments.structuredContent)}\nREVIEWS ${JSON.stringify(b.reviews.structuredContent)}\nPATCH ${JSON.stringify(b.patch.structuredContent)}\n`);
}

