	absRepo, err := filepath.Abs(repo)
	if err != nil {
		return err
	}
	key, err := providerRecordsKey(absRepo, repoKey(ctx, absRepo), providerVersion, tree, mode, options)
	if err != nil {
		return err
	}
	cache := cachedProviderRecords{
