func writeProviderRecords(path string, cache cachedProviderRecords) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	temporary, err := os.CreateTemp(dir, ".records-*.json.gz")
	if err != nil {
		return err
	}
