package sem

import (
	"crypto/sha256"
	"fmt"
	"os"
	"path/filepath"
)

// cacheEntry is an internally named artifact beneath a caller-selected cache
// directory. Cache families and versions are constants, and key is always the
// lowercase SHA-256 digest produced by the corresponding cache-key function.
// Keeping that invariant here makes the relative path non-injectable.
//
// Reads additionally go through os.Root. The cache directory itself is a
// caller-owned location and may be a symlink, but no descendant symlink can
// make an artifact read escape the directory OpenRoot actually opened.
type cacheEntry struct {
	root     string
	relative string
}

func newCacheEntry(cacheDir, family, version, key string) (cacheEntry, error) {
	if cacheDir == "" {
		return cacheEntry{}, fmt.Errorf("cache directory is empty")
	}
	if !validCachePathComponent(family) || !validCachePathComponent(version) {
		return cacheEntry{}, fmt.Errorf("invalid cache family or version")
	}
	if !validSHA256Hex(key) {
		return cacheEntry{}, fmt.Errorf("invalid cache key: want %d lowercase hexadecimal characters", sha256.Size*2)
	}
	return cacheEntry{
		root:     cacheDir,
		relative: filepath.Join(family, version, key+".json.gz"),
	}, nil
}

func validCachePathComponent(value string) bool {
	return value != "" && value != "." && value != ".." &&
		filepath.Base(value) == value && filepath.VolumeName(value) == ""
}

func validSHA256Hex(value string) bool {
	if len(value) != sha256.Size*2 {
		return false
	}
	for index := 0; index < len(value); index++ {
		if (value[index] < '0' || value[index] > '9') && (value[index] < 'a' || value[index] > 'f') {
			return false
		}
	}
	return true
}

func (entry cacheEntry) path() string {
	return filepath.Join(entry.root, entry.relative)
}

func (entry cacheEntry) open() (*os.File, error) {
	root, err := os.OpenRoot(entry.root)
	if err != nil {
		return nil, err
	}
	defer root.Close()
	return root.Open(entry.relative)
}
package sem

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestCacheEntryRequiresHashDerivedRelativePath(t *testing.T) {
	validKey := strings.Repeat("a", 64)
	entry, err := newCacheEntry("cache", "search", "v1", validKey)
	if err != nil {
		t.Fatalf("valid entry: %v", err)
	}
	want := filepath.Join("search", "v1", validKey+".json.gz")
	if entry.relative != want {
		t.Fatalf("relative path = %q, want %q", entry.relative, want)
	}

	for _, test := range []struct {
		name, family, version, key string
	}{
		{name: "short key", family: "search", version: "v1", key: strings.Repeat("a", 63)},
		{name: "uppercase key", family: "search", version: "v1", key: strings.Repeat("A", 64)},
		{name: "key traversal", family: "search", version: "v1", key: "../" + strings.Repeat("a", 61)},
		{name: "family traversal", family: "..", version: "v1", key: validKey},
		{name: "version traversal", family: "search", version: "../v1", key: validKey},
	} {
		t.Run(test.name, func(t *testing.T) {
			if _, err := newCacheEntry("cache", test.family, test.version, test.key); err == nil {
				t.Fatal("malicious cache entry was accepted")
			}
		})
	}
}

func TestCacheEntryReadRejectsSymlinkEscape(t *testing.T) {
	parent := t.TempDir()
	cacheDir := filepath.Join(parent, "cache")
	outsideDir := filepath.Join(parent, "outside")
	if err := os.MkdirAll(cacheDir, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(outsideDir, "search"), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(filepath.Join("..", "outside", "search"), filepath.Join(cacheDir, "search")); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}

	key := strings.Repeat("b", 64)
	outsideEntry, err := newCacheEntry(outsideDir, "search", "v1", key)
	if err != nil {
		t.Fatal(err)
	}
	if err := writeSearchSnapshot(outsideEntry, cachedSearchSnapshot{Tree: "outside"}); err != nil {
		t.Fatal(err)
	}
	escapingEntry, err := newCacheEntry(cacheDir, "search", "v1", key)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := readSearchSnapshot(escapingEntry); err == nil {
		t.Fatal("cache read followed a symlink outside the opened root")
	}
}

