	for depth := 0; depth <= searchVerifyMaxDepth; depth++ {
		candidate := searchVerifyJoin(dir, name)
		if evidence.exists(candidate) {
			return dir, candidate, true
		}
		if dir == "" {
			break
		}
		parent := path.Dir(dir)
		if parent == "." || parent == "/" || parent == dir {
			dir = ""
			continue
