 39	// providerRecordsKey derives the cache key for a record stream. It intentionally
 40	// folds in the caller-selected output mode (including
 41	// snapshot:compact-ndjson-v1) and the profile so native and compact snapshots
 42	// never collide, and it hashes the contents of
 43	// any --ignore-file / --include-file inputs so an edit to those files misses the
 44	// cache. OnlyFiles is included for completeness even though the record commands
 45	// do not expose it. Callers must NOT use this for --worktree runs (the working
 46	// tree can differ from HEAD) or for targeted --to/--from/--relation queries.
 47	func providerRecordsKey(absRepo, repositoryKey, providerVersion, tree, mode string, options ProviderSnapshotOptions) (string, error) {
 48		hash := sha256.New()
 49		writePart := func(value string) {
 50			_, _ = io.WriteString(hash, value)
 51			_, _ = io.WriteString(hash, "\x00")
 52		}
 53		writePart(providerRecordsCacheVersion)
 54		writePart(absRepo)
 55		// Repo identity PREFIXES EVERY SYMBOL ID this cache stores, so serving one repository's records
 56		// to another hands back IDs attributed to the wrong project. Reproduced by re-pointing a remote:
 57		// the warm run still reported gh/entireio/entire-graph after the checkout had become a fork.
 58		// searchSnapshotKey already folds this in; this key did not.
 59		writePart(repositoryKey)
 60		writePart(providerVersion)
 61		writePart(tree)
 62		writePart(mode)
 63		writePart(string(options.Profile))
 64		writePart(fmt.Sprintf("%d", options.MaxParseBytes))
 65		// Same graph-shaping argument as searchSnapshotKey: a capped build must not answer an uncapped
 66		// caller. This cache is the one that is ON BY DEFAULT, so the hole mattered more here.
 67		writePart(fmt.Sprintf("max-files=%d", options.MaxFiles))
 68		onlyFiles := append([]string(nil), options.OnlyFiles...)
 69		sort.Strings(onlyFiles)
 70		writePart("only-files")
 71		for _, filePath := range onlyFiles {
 72			writePart(filepath.ToSlash(filepath.Clean(filePath)))
 73		}
 74		for groupIndex, group := range [][]string{options.IgnoreFiles, options.IncludeFiles} {
 75			writePart(fmt.Sprintf("path-group-%d", groupIndex))
 76			paths := append([]string(nil), group...)
 77			sort.Strings(paths)
 78			for _, path := range paths {
 79				resolved := path
 80				if !filepath.IsAbs(resolved) {
 81					resolved = filepath.Join(absRepo, resolved)
 82				}
 83				writePart(filepath.Clean(resolved))
 84				content, err := os.ReadFile(resolved)
 85				if err != nil {
 86					if errors.Is(err, os.ErrNotExist) {
 87						writePart("missing")
 88						continue
 89					}
 90					return "", err
 91				}
 92				_, _ = hash.Write(content)
 93				writePart("")
 94			}
 95		}
 96		return hex.EncodeToString(hash.Sum(nil)), nil
 97	}
