764		}
765		for groupIndex, group := range [][]string{options.IgnoreFiles, options.IncludeFiles} {
766			writePart(fmt.Sprintf("path-group-%d", groupIndex))
767			// Preserve caller order: ignore matching is last-rule-wins, including
768			// across repeatable ignore/include files within each group.
