129	func callEvidenceSpan(evidence []sem.Evidence) (filePath string, start, end int, token string, ok bool) {
130		for _, item := range evidence {
131			if item.Kind != "call_site" || item.StartLine <= 0 {
132				continue
133			}
134			return item.FilePath, item.StartLine, item.EndLine, item.Detail, true
