 81	// newRepoLineReader reads files under repoRoot, memoizing per path so several
 82	// call sites in one file cost one read. It refuses oversized and NUL-bearing
 83	// files: neither can usefully be quoted.
 84	func newRepoLineReader(repoRoot string) lineReader {
 85		cache := map[string][]string{}
 86		return func(relPath string) ([]string, bool) {
 87			if relPath == "" || repoRoot == "" {
 88				return nil, false
 89			}
 90			if lines, ok := cache[relPath]; ok {
 91				return lines, lines != nil
 92			}
 93			// A relation's file path may have come from a loaded snapshot. Root.Open
 94			// rejects absolute/traversing paths and symlinks that escape repoRoot.
 95			root, err := os.OpenRoot(repoRoot)
 96			if err != nil {
 97				cache[relPath] = nil
 98				return nil, false
 99			}
100			defer root.Close()
101			file, err := root.Open(filepath.FromSlash(relPath))
102			if err != nil {
103				cache[relPath] = nil
104				return nil, false
105			}
106			defer file.Close()
107			info, err := file.Stat()
108			if err != nil || !info.Mode().IsRegular() || info.Size() > callSiteMaxFileBytes {
109				cache[relPath] = nil
110				return nil, false
111			}
112			content, err := io.ReadAll(io.LimitReader(file, callSiteMaxFileBytes+1))
113			if len(content) > callSiteMaxFileBytes {
114				err = io.ErrUnexpectedEOF
115			}
116			if err != nil || strings.IndexByte(string(content), 0) >= 0 {
117				cache[relPath] = nil
118				return nil, false
119			}
120			lines := strings.Split(strings.ReplaceAll(string(content), "\r\n", "\n"), "\n")
121			cache[relPath] = lines
122			return lines, true
123		}
124	}
