 46	func loadWorktreeIgnoreMatcher(repo string, ignoreFiles, includeFiles []string) (ignoreMatcher, error) {
 47		var matcher ignoreMatcher
 48		if err := matcher.loadOptional(filepath.Join(repo, ".gitignore"), false); err != nil {
 49			return ignoreMatcher{}, err
 50		}
