110	// worktree, where it holds "gitdir: <path to .git/worktrees/<name>>". Git shares
111	// info/ across worktrees via that gitdir's commondir pointer, so the exclude file
112	// lives under the common directory, not under <repo>/.git.
113	func gitInfoExcludePath(repo string) string {
114		dotGit := filepath.Join(repo, ".git")
115		info, err := os.Stat(dotGit)
116		if err != nil {
