119		if info.IsDir() {
120			return filepath.Join(dotGit, "info", "exclude")
121		}
122		if !info.Mode().IsRegular() {
123			return ""
124		}
125		raw, err := os.ReadFile(dotGit)
126		if err != nil {
127			return ""
128		}
129		gitDir := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(string(raw)), "gitdir:"))
130		if gitDir == "" {
131			return ""
132		}
